const source = (c, kind) => ({
  id: c.id, s: c.s, u: c.u, axe: c.axe || 'fournisseurs', nature: c.nature || 'editeur',
  primaire: c.primaire !== false, filtre: '', cnil: false, decision: !!c.decision, arxiv: false, role: 'tri', kind,
