const avant = { prep: sd.prep || null, semaine: sd.semaine || null };
sd.prep = { semaine: semaine.cle, at: maintenant, fichier: nom, nb: total, threadId: null, messageId: null, rappel: false };
sd.semaine = { depuis: maintenant, collectes: 0, parSource: {} };
sd._passage = Object.assign(sd._passage || {}, { prepAvant: avant, preparation: { fichier: nom, candidats: total, reserve: (sel.reserve || []).length } });
return [{ json: {
  markdown, nom, chemin: '/home/node/.n8n-files/parlia/' + nom, semaine: semaine.cle, candidats: total,
  discord: { ouverture, fiches },
} }];

// Le message d'ouverture de la semaine, préparé par le nœud Préparation. Sans webhook Discord réglé, rien ne part :
// la branche s'arrête ici, et le fichier reste la seule trace de la préparation.
const plan = $('Que faire ?').first().json;
const prep = $input.first().json || {};
if (!plan.reglages || !plan.reglages.discord || !prep.discord || !prep.discord.ouverture) return [];
return [{ json: Object.assign({ threadId: null }, prep.discord.ouverture) }];

// Les fiches guidées et la réserve, après l'ouverture. En forum, l'ouverture a créé le post de la semaine :
// la réponse de Discord (?wait=true) donne son identifiant (channel_id), que suivent les fiches, puis le rappel.
// Si l'ouverture a échoué (réseau absent au réveil du Mac, webhook supprimé…), rien ne part : la préparation est
// retirée de la mémoire et repart au passage suivant, trois fois au plus dans la semaine. Le fichier, déjà
// écrit, est alors réécrit. En mode essai, le nœud Discord est désactivé : les fiches sont seulement préparées.
const sd = $getWorkflowStaticData('global');
const plan = $('Que faire ?').first().json;
const reglages = plan.reglages || {};
const prep = $('Préparation').first().json;
const rep = $input.first().json || {};
const ok = !rep.error && !!rep.id;
if (!sd._passage) sd._passage = {};
if (!ok && !plan.essai) {
  const cle = prep.semaine;
  const n = sd.echecsOuverture && sd.echecsOuverture.semaine === cle ? sd.echecsOuverture.n + 1 : 1;
  sd.echecsOuverture = { semaine: cle, n };
  const erreur = rep.error;
  const detail = erreur ? String(typeof erreur === 'string' ? erreur : erreur.message || JSON.stringify(erreur)).slice(0, 160) : 'réponse sans identifiant';
  const avant = sd._passage.prepAvant;
  if (n < 3 && avant) {
    if (avant.prep) sd.prep = avant.prep;
    else delete sd.prep;
    if (avant.semaine) sd.semaine = avant.semaine;
  }
  sd._passage.discord = { ouverture: 'échec', detail, essai: n, abandon: n >= 3 };
  return [];
}
let threadId = null;
if (ok) {
  if (reglages.forum) threadId = String(rep.channel_id || rep.id);
  if (sd.prep && sd.prep.semaine === prep.semaine) {
    sd.prep.threadId = threadId;
    sd.prep.messageId = String(rep.id);
  }
  delete sd.echecsOuverture;
}
const liste = (prep.discord && prep.discord.fiches) || [];
sd._passage.discord = { ouverture: ok ? 'ok' : 'essai', fiches: liste.length };
return liste.map((f) => ({ json: Object.assign({}, f, { threadId }) }));

// Le rappel doux (ergonomie.md, F2) : au premier passage après le jeudi 16 h 30 (réglable), une fois, si la
// préparation de la semaine est partie avant, et si la séance de la semaine n'a pas eu lieu. Les notes de séance
// le disent (nœud Notes) : une note tenue cette semaine, et le rappel n'a pas lieu d'être. Notes illisibles
// (dossier non monté) : il part quand même, avec « si c'est fait, ignore ce message ». Il va dans le post de la
// semaine (forum) et mentionne Louis si la mention est réglée.
const sd = $getWorkflowStaticData('global');
const plan = $('Que faire ?').first().json;
if (!plan.rappel) return [];
const reglages = plan.reglages || {};
const prep = sd.prep || {};
const notes = (sd._passage && sd._passage.notes) || null;
const notesLues = !!(notes && notes.lisibles);
if (sd.prep) sd.prep.rappel = true;
if (notesLues && notes.seanceSemaine) {
  sd._passage = Object.assign(sd._passage || {}, { rappel: 'inutile', rappelSeance: notes.seanceSemaine });
  return [];
}
sd._passage = Object.assign(sd._passage || {}, { rappel: reglages.discord ? 'préparé' : 'sans Discord' });
if (!reglages.discord) return [];
const mention = reglages.mention ? '<@' + reglages.mention + '> ' : '';
const nb = Number(prep.nb) || 0;
const payload = {
  username: 'Veille · ParlIA',
  content: mention + '⏰ Petit rappel : le dossier de la semaine ' + plan.semaine.numero + " t'attend"
    + (nb ? ' (' + nb + ' fiche' + (nb > 1 ? 's' : '') + ')' : '') + ", jusqu'à dimanche soir. Une fiche lue et une ligne de "
    + "réponse, c'est déjà une séance courte."
    + (notesLues ? " Aucune note de séance cette semaine pour l'instant." : " Si c'est fait, ignore ce message."),
  allowed_mentions: reglages.mention ? { parse: [], users: [reglages.mention] } : { parse: [] },
};
let threadId = null;
if (reglages.forum) {
  if (prep.threadId) threadId = prep.threadId;
  else payload.thread_name = ('Rappel · semaine ' + plan.semaine.numero).slice(0, 100);
}
return [{ json: { payload, cv2: false, threadId } }];

// ---- Outils communs de la veille ParlIA (workflows/src-parlia/outils.js) ----
// build_parlia.py place ce fichier en tête de chaque nœud Code : n8n ne permet pas d'importer un module.
const PARLIA = {
  AXES: ['fournisseurs', 'qualite', 'conformite', 'exploitation'],
  NOM_AXE: {
    fournisseurs: 'Fournisseurs et coûts', qualite: "Qualité de l'étiquetage", conformite: 'Conformité',
    exploitation: 'Exploitation', hors_theme: 'Hors thème',
  },
  NATURES: ['editeur', 'institution', 'auteurs', 'praticien', 'presse', 'agregateur', 'inconnu'],
  NOM_NATURE: {
    editeur: 'éditeur', institution: 'institution', auteurs: 'auteurs', praticien: 'praticien', presse: 'presse',
    agregateur: 'agrégateur', inconnu: 'nature inconnue',
  },
  THEME: "« Étiqueter les questions écrites du Sénat avec un modèle de langage commercial : choisir, mesurer et pouvoir remplacer le fournisseur, dans le respect du RGPD et du règlement européen sur l'IA. »",
  // Les modèles suivis (sources.md, 4.4) : leurs changements de prix et leurs retraits sont toujours proposés.
  SUIVI: [
    'openai/gpt-6-luna', 'anthropic/claude-haiku-5.5', 'mistralai/mistral-small-3.2-24b-instruct',
    'openai/gpt-4o-mini', 'openai/gpt-6.1-terra', 'google/gemini-4-argon',
  ],
  // Les mêmes, et les modèles de décision, tels qu'on les reconnaît dans un titre ou un extrait.
  NOMS_SUIVIS: /\b(gpt-6-luna|gpt-6 luna|decisions api|claude haiku 5\.5|claude-haiku-5\.5|mistral small 3\.2|mistral-small-3\.2|gpt-4o mini|gpt-4o-mini|gpt-6\.1[- ]terra|gemini 4 argon|gemini-4-argon|jev|clef|clef-flash|d1|d1-ultra|decider)\b/i,
  UA: 'veille-parlia/1.0 (veille de certification de Louis; +https://github.com/lougail)',
};

// Texte lisible : sans balises ni entités, espaces réduits.
function texteSimple(s) {
  return String(s == null ? '' : s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;|&#x27;|&rsquo;|&lsquo;/gi, "'").replace(/&laquo;/gi, '«').replace(/&raquo;/gi, '»')
    .replace(/&[a-z]+;|&#\d+;/gi, ' ')
    .replace(/\s+/g, ' ').trim();
}
function tronquer(s, n) {
  const t = String(s == null ? '' : s);
  if (t.length <= n) return t;
  const coupe = t.lastIndexOf(' ', n - 1);
  return t.slice(0, coupe > n * 0.6 ? coupe : n - 1).trim() + '…';
}
// Empreinte courte et stable (djb2), pour reconnaître un texte déjà vu sans le garder.
function hacher(s) {
  let h = 5381;
  const t = String(s);
  for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) >>> 0;
  return h.toString(36);
}
// Le domaine d'une adresse ; new URL() n'existe pas dans le bac à sable de n8n.
function domaineDe(url) {
  const m = /^https?:\/\/([^/?#:]+)/i.exec(String(url || ''));
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}
// La clé d'une adresse, pour le dédoublonnage : sans protocole, sans www, sans paramètres de suivi.
function cleAdresse(url) {
  const m = /^https?:\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i.exec(String(url || '').trim());
  if (!m) return '';
  const hote = m[1].toLowerCase().replace(/^(www|m)\./, '');
  const chemin = m[2].replace(/\/+$/, '');
  let requete = '';
  if (m[3]) {
    const garde = m[3].slice(1).split('&').filter((p) => p && !/^(utm_|ref=|fbclid|gclid)/i.test(p)).sort();
    if (garde.length) requete = '?' + garde.join('&');
  }
  return hote + chemin + requete;
}
// Une cellule de tableau Markdown : ni barre verticale ni retour à la ligne.
function cellule(s) {
  return String(s == null ? '' : s).replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ').trim();
}
// Un texte pour Discord : mentions collectives neutralisées.
function pourDiscord(s) {
  return String(s == null ? '' : s).replace(/@(everyone|here)/gi, '@\u200b$1');
}
// Une date ISO (AAAA-MM-JJ) en toutes lettres : « 4 novembre 2026 », « 1er décembre 2026 ».
const MOIS_FR = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
function dateLongue(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  if (!m) return '';
  return Number(m[3]) + (m[3] === '01' ? 'er' : '') + ' ' + MOIS_FR[Number(m[2]) - 1] + ' ' + m[1];
}
// La première date écrite dans un texte (pages sans flux) : 2026-10-14, October 14, 2026, 14 octobre 2026,
// ou 10.22.2026 (mois.jour.année, chez Liquid AI). Renvoie AAAA-MM-JJ, ou une chaîne vide.
const MOIS_EN = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };
function dateDansTexte(texte) {
  const t = String(texte || '');
  const deux = (n) => String(n).padStart(2, '0');
  const candidats = [];
  let m = /\b(20\d{2})-(\d{2})-(\d{2})\b/.exec(t);
  if (m && Number(m[2]) <= 12 && Number(m[3]) <= 31) candidats.push({ i: m.index, d: m[1] + '-' + m[2] + '-' + m[3] });
  m = /\b(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\.?\s+(\d{1,2}),?\s+(20\d{2})\b/i.exec(t);
  if (m) candidats.push({ i: m.index, d: m[3] + '-' + deux(MOIS_EN[m[1].toLowerCase()]) + '-' + deux(m[2]) });
  m = /\b(\d{1,2})(?:er)?\s+(janvier|février|fevrier|mars|avril|mai|juin|juillet|août|aout|septembre|octobre|novembre|décembre|decembre)\s+(20\d{2})\b/i.exec(t);
  if (m) {
    const mois = m[2].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const n = ['janvier', 'fevrier', 'mars', 'avril', 'mai', 'juin', 'juillet', 'aout', 'septembre', 'octobre', 'novembre', 'decembre'].indexOf(mois) + 1;
    if (n) candidats.push({ i: m.index, d: m[3] + '-' + deux(n) + '-' + deux(m[1]) });
  }
  m = /\b(\d{1,2})\.(\d{1,2})\.(20\d{2})\b/.exec(t);
  if (m && Number(m[1]) <= 12 && Number(m[2]) <= 31) candidats.push({ i: m.index, d: m[3] + '-' + deux(m[1]) + '-' + deux(m[2]) });
  candidats.sort((a, b) => a.i - b.i);
  return candidats.length ? candidats[0].d : '';
}
// La santé d'une source : un échec de plus, ou un retour. Au troisième échec de suite, une seule alerte
// (sd._passage.flux, lue par le message de #status) ; au retour, un message de retour.
function noterSante(sd, id, nom, ok, detail, maintenant) {
  if (!sd.sante) sd.sante = {};
  if (!sd._passage) sd._passage = {};
  if (!sd._passage.flux) sd._passage.flux = [];
  const e = sd.sante[id] || { s: nom, echecs: 0, alerte: false };
  e.s = nom || e.s;
  if (ok) {
    if (e.alerte) sd._passage.flux.push({ id, s: e.s, retour: true });
    e.echecs = 0;
    e.alerte = false;
    e.detail = '';
    e.dernierOk = maintenant;
  } else {
    e.echecs = (e.echecs || 0) + 1;
    e.detail = String(detail || '').slice(0, 160);
    if (e.echecs >= 3 && !e.alerte) {
      e.alerte = true;
      sd._passage.flux.push({ id, s: e.s, echecs: e.echecs, detail: e.detail });
    }
  }
  sd.sante[id] = e;
}
// Une alerte immédiate (remaniement, attributions, retrait d'un modèle suivi), envoyée par le nœud Alertes.
function pousserAlerte(sd, alerte) {
  if (!sd._alertes) sd._alertes = [];
  alerte.cle = alerte.cle || hacher(alerte.type + '|' + (alerte.id || alerte.url || alerte.titre));
  if (!sd._alertes.some((a) => a.cle === alerte.cle)) sd._alertes.push(alerte);
}
// ---- Fin des outils communs ----

// Le message de #status (DISCORD_WEBHOOK_STATUS) : ce que le passage a fait, en quelques lignes, à l'heure de Paris.
// Silencieux (drapeau 4096), sauf problème : une source en échec trois fois de suite, le fichier non écrit, un
// envoi Discord refusé. Il lit le carnet du passage (sd._passage), rempli par les autres nœuds, puis l'efface,
// et les sorties des nœuds d'écriture et d'envoi (en erreur, ils continuent : continueOnFail).
const sd = $getWorkflowStaticData('global');
const plan = $('Que faire ?').first().json;
const reglages = plan.reglages || {};
const p = sd._passage || {};
delete sd._passage;
const JOURS = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'];
const quand = JOURS[$now.weekday - 1] + ' ' + ($now.day === 1 ? '1er' : $now.day) + ' ' + MOIS_FR[$now.month - 1] + ', '
  + $now.hour + ' h ' + String($now.minute).padStart(2, '0');
// La sortie d'un nœud : le nombre d'éléments et les erreurs ; null s'il n'a pas tourné. Les noms sont écrits en
// toutes lettres à l'appel ($('Écrire le fichier')) : le task runner de n8n y repère les données à transmettre.
function sortieDe(lire) {
  try {
    const n = lire();
    if (n.isExecuted === false) return null;
    const items = n.all();
    const err = items.map((i) => i.json && i.json.error).filter(Boolean)
      .map((e) => String(typeof e === 'string' ? e : e.message || JSON.stringify(e)).slice(0, 120));
    return { n: items.length, err };
  } catch (e) {
    return null;
  }
}
const lignes = ['**Veille ParlIA** — ' + quand + (plan.essai ? ' · ESSAI' : '')];
let probleme = false;
if (p.collecte) {
  const c = p.collecteStats || {};
  const t = p.tri;
  let l = '📥 ' + (c.lus || 0) + ' lus → 🆕 ' + (c.nouveaux || 0) + ' nouveaux';
  if (t) {
    const axes = PARLIA.AXES.filter((a) => t.parAxe && t.parAxe[a]).map((a) => a + ' ' + t.parAxe[a]).join(' · ');
    l += ' → 🏷️ ' + (t.nouveaux - (t.horsTheme || 0)) + ' dans le thème' + (axes ? ' (' + axes + ')' : '') + ', ' + (t.horsTheme || 0) + ' hors thème';
    if (t.secours) l += ' · ⚠️ ' + t.secours + ' au tri de secours';
  }
  lignes.push(l);
  const extras = [];
  if (p.sommeilH && p.sommeilH > 12) extras.push('🕒 rattrapage : ' + Math.round(p.sommeilH) + ' h depuis la dernière collecte');
  if (p.pages) {
    extras.push('🌐 pages et API : ' + (p.pages.lues - p.pages.echecs.length) + '/' + p.pages.lues + ' lues, ' + p.pages.nouveautes + ' nouveauté(s)'
      + (p.pages.refaites.length ? ', refaites : ' + p.pages.refaites.join(', ') : ''));
  }
  if (p.jorf) extras.push('⚖️ Journal officiel : ' + p.jorf.archives + ' archive(s), ' + p.jorf.decrets + ' décret(s)' + (p.jorf.erreur ? ' · ' + p.jorf.erreur : ''));
  if (extras.length) lignes.push(extras.join(' · '));
}
if (p.alertes && p.alertes.nouvelles) {
  const envoi = sortieDe(() => $('Discord alertes'));
  const ko = envoi && envoi.err.length;
  if (ko) probleme = true;
  lignes.push('🚨 ' + p.alertes.nouvelles + ' alerte(s) : ' + p.alertes.types.join(', ')
    + (!reglages.discord ? ' (Discord non réglé : voir le fichier de la semaine)' : ko ? ' · ❌ envoi refusé : ' + envoi.err[0] : ''));
}
if (p.preparation) {
  const prep = p.preparation;
  lignes.push('📂 Préparation de la semaine ' + plan.semaine.numero + ' : ' + prep.candidats + ' candidat(s), ' + prep.reserve + ' en réserve');
  const ecrit = sortieDe(() => $('Écrire le fichier'));
  if (ecrit && !ecrit.err.length) lignes.push('📄 ' + prep.fichier + ' écrit dans le dossier d\'export');
  else {
    probleme = true;
    lignes.push('❌ fichier non écrit' + (ecrit && ecrit.err.length ? ' : ' + ecrit.err[0] : '') + ' (dossier monté ? voir docs/veille-parlia.md)');
  }
  const d = p.discord;
  if (!reglages.discord) lignes.push('💬 Discord non réglé (DISCORD_WEBHOOK_PARLIA) : rien publié');
  else if (d && d.ouverture === 'échec') {
    probleme = true;
    lignes.push("❌ ouverture refusée par Discord (" + d.detail + ') : ' + (d.abandon ? 'abandon après trois essais cette semaine' : 'nouvel essai au prochain passage'));
  } else if (d) {
    const envoi = sortieDe(() => $('Discord fiches'));
    const ko = envoi ? envoi.err.length : 0;
    if (ko) probleme = true;
    lignes.push('💬 Discord : ouverture ' + (d.ouverture === 'ok' ? 'publiée' : 'préparée (essai)') + ', ' + (d.fiches - ko) + '/' + d.fiches + ' fiche(s) et réserve'
      + (ko ? ' · ❌ ' + envoi.err[0] : ''));
  }
}
if (p.notes && (p.preparation || p.rappel)) {
  const n = p.notes;
  lignes.push('📓 Notes de séance : ' + (n.lisibles
    ? n.lues + ' lue(s), ' + n.tenues + ' tenue(s)' + (n.derniere ? ' ; dernière : séance ' + n.derniere.numero + ', ' + dateLongue(n.derniere.fin) : '')
    : 'non lues (' + n.motif + ')'));
}
if (p.rappel === 'inutile') {
  const s = p.rappelSeance || {};
  lignes.push('⏰ Rappel du jeudi : inutile, séance ' + (s.numero || '?') + ' tenue ' + (s.debut ? 'le ' + dateLongue(s.debut) : 'cette semaine'));
} else if (p.rappel) {
  const envoi = sortieDe(() => $('Discord rappel'));
  const ko = envoi && envoi.err.length;
  if (ko) probleme = true;
  lignes.push('⏰ Rappel du jeudi : ' + (p.rappel === 'sans Discord' ? 'Discord non réglé' : ko ? '❌ ' + envoi.err[0] : plan.essai ? 'préparé (essai)' : 'envoyé'));
}
const alertesFlux = (p.flux || []).filter((f) => !f.retour);
const retours = (p.flux || []).filter((f) => f.retour);
if (alertesFlux.length) {
  probleme = true;
  lignes.push('⚠️ En échec ' + alertesFlux[0].echecs + ' fois de suite : ' + alertesFlux.map((f) => f.s + (f.detail ? ' (' + f.detail + ')' : '')).join(' ; '));
}
if (retours.length) lignes.push('✅ De retour : ' + retours.map((f) => f.s).join(', '));
if (!reglages.statut) return [];
const payload = { username: 'Veille · ParlIA', content: lignes.join('\n').slice(0, 1900), allowed_mentions: { parse: [] } };
if (!probleme) payload.flags = 4096;
return [{ json: { payload, cv2: false, threadId: null, probleme } }];
